/**
 * @brief Strategy for handling duplicate key frame tiles in animation decompilation.
 *
 * @details
 * When decompiling animations, it's possible for multiple key frame tiles to be identical. This is
 * problematic because during recompilation, identical tiles cannot be distinguished. This enum
 * determines how to handle such cases.
 *
 */
enum class AnimKeyFrameResolutionStrategy {
    /**
     * @brief Emit a formatted error and fail decompilation.
     */
    error,
    /**
     * @brief Emit a warning and continue decompilation.
     */
    warning,
    /**
     * @brief Mangle duplicate tiles to make them unique, then backport changes to tiles.png.
     */
    mangle
};

